  if(existing)return {existing};
  return {ui,item,fields:{queryKey:key,accountId:owner(),city:item.city,country:item.country,catalogueId:item.id,accommodationKind:item.kind,stars:item.stars,benefits:item.features.includes('含早餐')?'含早餐':'不含早餐',rooms,adults,children,category:ui.category,hours:ui.category==='hourly'?ui.hours:undefined,preferences:[...ui.preferredTags]}};
